"""
Royals Intelligence - Verified Domestic Competition and Match Catalog Cache
Provides fallback platform records for seasons 2022, 2023, 2024, 2025, and 2026
when raw untracked datasets are unmounted in containerized production environments.
"""

import base64
import json
import zlib
from typing import Optional
import pandas as pd

_COMPRESSED_CATALOG = ""

_cached_comps_df: Optional[pd.DataFrame] = None
_cached_matches_df: Optional[pd.DataFrame] = None


def _load_catalog():
    global _cached_comps_df, _cached_matches_df
    if _cached_comps_df is not None and _cached_matches_df is not None:
        return _cached_comps_df, _cached_matches_df

    data = json.loads(zlib.decompress(base64.b64decode(_COMPRESSED_CATALOG.encode('ascii'))).decode('utf-8'))
    _cached_comps_df = pd.DataFrame(data['competitions'])
    _cached_matches_df = pd.DataFrame(data['matches'])
    return _cached_comps_df, _cached_matches_df


def get_fallback_competitions_df() -> pd.DataFrame:
    comps_df, _ = _load_catalog()
    return comps_df.copy()


def get_fallback_matches_df() -> pd.DataFrame:
    _, matches_df = _load_catalog()
    return matches_df.copy()
